let seed,mySize;
let angle_c;
let colors = [];

let colors4 = "8c75ff-c553d2-2dfd60-2788f5-23054f".split("-").map((a) => "#" + a);
let colors5 = "f21252-8834f1-c4dd92-184fd3-f9fee2".split("-").map((a) => "#" + a);
let colors6 = "2E294E-541388-F1E9DA-FFD400-D90368".split("-").map((a) => "#" + a);
let colors7 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a);
let colors8 = "e9baaa-ffa07a-164555-ffe1d0-acd9e7".split("-").map((a) => "#" + a);
var color_setup;

function setup() {
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize);
	seed = int(random(1000));
	colorMode(HSB, 360, 100, 100, 100);
	background(0, 0, 95, 100);
	color_setup = random([ colors4, colors5, colors6, colors7, colors8]);
	angle_c = 0;
}

function draw() {
	randomSeed(seed);
	drawingContext.shadowColor = str(random(color_setup)) + "00";
	drawingContext.shadowOffsetX = 0;
	drawingContext.shadowOffsetY = 0;
	drawingContext.shadowBlur = 0;
	// background(0, 0, 95, 1);

	translate(width / 2, height / 2);
	rotate(angle_c);
	for (let i = 0; i < 4; i++) {
		colors[0] = random(color_setup);
		colors[1] = random(color_setup);
		colors[2] = random(color_setup);
		colors[3] = random(color_setup);
		colors[4] = random(color_setup);
		circleForm(0, 0, mySize * 0.2 * (i + 1));
	}
}

function circleForm(x, y, d) {

	let branch = int(random(1,5));
	let ang = TAU / branch;
	let angles = [];
	for (let i = 0; i < branch; i++) {
		angles.push(ang * (i + iteration(0.1, 0.25)));
	}
	for (let i = 0; i < branch; i++) {
		let ang1 = angles[i];
		let ang2 = angles[(i + int(random(6))) % angles.length];
		let dd = d * iteration(0.1, 1);
		noFill();
		drawingContext.shadowColor = random(color_setup);
		drawingContext.shadowOffsetX = random(-2,2);
		drawingContext.shadowOffsetY = random(-2,2);
		drawingContext.shadowBlur = 0;
		stroke(random(color_setup));

		strokeWeight(random(1));
		circle(x, y, dd);
	}
angle_c+=TAU/360;
}

function iteration(s, e) {
	let t = random(10, 100);
	let v = random(0.001, 0.01);
	return map(cos(t + frameCount * v), -1, 1, s, e);
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("0215_MovingArc_7_record_2022", "png");
	}
}

